"""Generated files: MATRIX.md, the README catalog block and the site's data."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

from cook.engines import DIALECTS, LABELS, available
from cook.model import Recipe, Repo
from cook.run import Outcome, run_all
from cook.sync import synced_page

HEADER = "<!-- Generated by `cook generate`. Do not edit by hand. -->\n\n"
README_START = "<!-- cook:catalog -->"
README_END = "<!-- /cook:catalog -->"

CELL = {"pass": "✓", "fail": "✗", "error": "✗", "unsupported": "–", "skipped": "·"}


def page_path(r: Recipe) -> str:
    return f"recipes/{r.category}/{r.slug}/recipe.md"


def _results(repo: Repo) -> tuple[dict[str, dict[str, Outcome]], dict[str, str]]:
    engines = available()
    results = run_all(repo.recipes, engines)
    versions = {d: e.version() for d, e in engines.items()}
    return results, versions


def _cell(r: Recipe, outcomes: dict[str, Outcome], d: str) -> str:
    if d in r.unsupported:
        return "–"
    o = outcomes.get(d)
    if o is None:
        return "·"
    mark = CELL[o.status]
    return f"{mark}*" if o.status == "pass" and r.is_variant(d) else mark


def matrix(
    repo: Repo, results: dict[str, dict[str, Outcome]], versions: dict[str, str]
) -> str:
    out = [HEADER, "# Compatibility matrix\n\n"]
    out.append(
        "Every recipe, run on every engine by `cook generate`. "
        "`✓` the shared query passes, `✓*` a dialect-specific variant passes, "
        "`–` the engine can't do it (the page says why), "
        "`·` not run on this machine.\n\n"
        "CI runs this on PostgreSQL 16, 17 and 18, MySQL 8.0, 8.4 and 9, and the "
        "SQLite and DuckDB builds that ship with Python. The website shows the "
        "exact versions of the run that built it.\n\n"
    )
    out.append("| Recipe | " + " | ".join(LABELS[d] for d in DIALECTS) + " |\n")
    out.append("|---|" + ":---:|" * len(DIALECTS) + "\n")
    for cat in repo.categories:
        items = [r for r in repo.ordered() if r.category == cat["id"]]
        if not items:
            continue
        out.append(f"| **{cat['label']}** |" + " |" * len(DIALECTS) + "\n")
        for r in items:
            cells = " | ".join(_cell(r, results[r.slug], d) for d in DIALECTS)
            out.append(f"| [{r.meta['title']}]({page_path(r)}) | {cells} |\n")
    return "".join(out)


def readme_catalog(repo: Repo, results: dict[str, dict[str, Outcome]]) -> str:
    total = len(repo.recipes)
    out = [
        f"\n**{total} recipes** in {len(repo.categories)} categories. "
        "Open a category to see what's inside.\n\n"
    ]
    for cat in repo.categories:
        items = [r for r in repo.ordered() if r.category == cat["id"]]
        if not items:
            continue
        out.append(
            f"<details>\n<summary><b>{cat['label']}</b> · {len(items)}</summary>\n\n"
        )
        for r in items:
            missing = [LABELS[d] for d in DIALECTS if d in r.unsupported]
            note = f" *(not on {', '.join(missing)})*" if missing else ""
            title, summary = r.meta["title"], r.meta["summary"]
            out.append(f"- [{title}]({page_path(r)}): {summary}{note}\n")
        out.append("\n</details>\n")
    return "".join(out)


def readme(repo: Repo, results: dict[str, dict[str, Outcome]]) -> str:
    text = (repo.root / "README.md").read_text(encoding="utf-8")
    start, end = text.find(README_START), text.find(README_END)
    if start == -1 or end == -1:
        return text
    head = text[: start + len(README_START)]
    return head + "\n" + readme_catalog(repo, results) + text[end:]


def site_meta(
    repo: Repo, results: dict[str, dict[str, Outcome]], versions: dict[str, str]
) -> dict[str, Any]:
    ordered = repo.ordered()
    counts = {c["id"]: 0 for c in repo.categories}
    recipes = []
    for i, r in enumerate(ordered):
        counts[r.category] += 1
        queries = {}
        for d in DIALECTS:
            path = r.query_file(d)
            if path is not None:
                queries[d] = {
                    "sql": r.query(d),
                    "variant": r.is_variant(d),
                    "file": path.name,
                }
        recipes.append(
            {
                "slug": r.slug,
                "title": r.meta["title"],
                "summary": r.meta["summary"],
                "category": r.category,
                "tags": r.meta.get("tags") or [],
                "fixture": r.fixture,
                "ordered": r.ordered,
                "published": r.meta["published"].isoformat(),
                "setup": {d: r.setup(d) for d in DIALECTS},
                "queries": queries,
                "unsupported": r.unsupported,
                "expected": r.expected,
                "results": {
                    d: {"status": o.status, "detail": o.detail}
                    for d, o in results[r.slug].items()
                },
                "related": r.meta.get("related") or [],
                "previous": ordered[i - 1].slug if i else None,
                "next": ordered[i + 1].slug if i + 1 < len(ordered) else None,
            }
        )
    return {
        "version": _version(repo.root),
        "dialects": list(DIALECTS),
        "labels": LABELS,
        "versions": versions,
        "verifiedAt": os.environ.get("COOK_VERIFIED_AT", ""),
        "categories": [{**c, "count": counts[c["id"]]} for c in repo.categories],
        "tags": repo.tags,
        "fixtures": repo.fixtures,
        "recipes": recipes,
    }


def _version(root: Path) -> str:
    for line in (root / "pyproject.toml").read_text(encoding="utf-8").splitlines():
        if line.startswith("version ="):
            return line.split('"')[1]
    return "0.0.0"


def generate(repo: Repo, *, check: bool, site: bool) -> list[str]:
    results, versions = _results(repo)
    bad = [
        f"{slug} on {d}: {o.detail.splitlines()[0] if o.detail else o.status}"
        for slug, per in results.items()
        for d, o in per.items()
        if o.status in ("fail", "error")
    ]
    if bad:
        raise SystemExit("cook: fix these before generating:\n  " + "\n  ".join(bad))
    files = {repo.root / "MATRIX.md": matrix(repo, results, versions)}
    for recipe in repo.recipes:
        files[recipe.page] = synced_page(recipe)
    if (repo.root / "README.md").is_file():
        files[repo.root / "README.md"] = readme(repo, results)
    stale = []
    for path, text in files.items():
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current != text:
            stale.append(str(path.relative_to(repo.root)))
            if not check:
                path.write_text(text, encoding="utf-8")
    if site and not check:
        out = repo.root / "site" / "src" / "generated" / "meta.json"
        out.parent.mkdir(parents=True, exist_ok=True)
        data = site_meta(repo, results, versions)
        out.write_text(
            json.dumps(data, indent=2, ensure_ascii=False, default=str) + "\n"
        )
    return stale
